#include <bits/stdc++.h>
using namespace std;

#define END 42

int point[50];
int nxt[50];
int dat[10];
int loc[4] = {0,};
int answer = 0;

void move(int k, int result) {
    if (k == 10) {
        answer = max(answer, result);
        return;
    }

    for (int p = 0; p < 4; p++) {
        int pre = loc[p];
        int cur = pre;

        if (pre == 10 || pre == 20 || pre == 30) cur += 1;

        for (int i = 0; i < dat[k]; i++) cur = nxt[cur];

        if (cur != END && find(loc, loc + 4, cur) != loc + 4) return;

        loc[p] = cur;
        move(k + 1, result + point[cur]);
        loc[p] = pre;
    }
}

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);

    for (int i = 0; i < 10; i++) cin >> dat[i];

    for (int i = 0; i < 45; i++) {
        nxt[i] = i + 2;
        point[i] = i;
    }

    point[END] = 0;
    nxt[END] = END;

    point[11] = 10; point[13] = 13; point[15] = 16; point[17] = 19;
    nxt[17] = 41;

    point[21] = 20; point[23] = 22; point[25] = 24;
    nxt[25] = 41;

    point[31] = 30; point[33] = 28; point[35] = 27; point[37] = 26;
    nxt[37] = 41;

    point[41] = 25; point[43] = 30; point[45] = 35;
    nxt[45] = 40;

    move(0, 0);

    cout << answer;

    return 0;
}

