위 문제를 해결하기 위한 C++  코드를 작성해보았어.

```
#include <bits/stdc++.h>
using namespace std;

int dat[100001];
int n, k, answer = 0;

int main() {
    ios::sync_with_stdio(0);
    cin.tie(0);

    cin >> n >> k;

    for (int i = 1; i <= n; i++) cin >> dat[i];

    priority_queue<pair<int, int>> PQ;
    for (int i = 1; i < k; i++) PQ.push({-dat[i], i});

    for (int i = 1; i + k - 1 <= n; i++) {
        PQ.push({-dat[i + k - 1], i + k - 1});

        while (PQ.top().second < i) PQ.pop();

        auto [cost, idx] = PQ.top(); PQ.pop();
        for (; i < idx; i++) PQ.push({-dat[i + k - 1], i + k - 1});

        answer = max(answer, -cost);
    }

    cout << answer;

    return 0;
}
```

